WITH x9 AS (SELECT x7.HEX(WEIGHT_STRING(JSON_UNQUOTE(JSON_SET('{}', '$', '')))) FROM x17) SELECT x7.HEX(WEIGHT_STRING(JSON_UNQUOTE(JSON_SET('{}', '$', '')))), x7.HEX('тест'), AVG(CASE WHEN x7.HEX('тест') > 1 THEN 1 / NULLIF(1, 0) ELSE (JSON_EXTRACT(x7.HEX(WEIGHT_STRING(JSON_UNQUOTE(JSON_SET('{}', '$', '')))), '$')) END) AS x4, x7.HEX('тест') FROM v64472 AS x7 WHERE x7.HEX('тест') = x7.HEX(WEIGHT_STRING(JSON_UNQUOTE(JSON_SET('{}', '$', '')))) AND x7.HEX(INET_ATON('127.1')) <= 1